def unit_of_work(metadata=None, timeout=None):
    def do_work(func):
        def wrapper(*args, **kwargs):
            tx = args[0]
            metadata = metadata or kwargs.get("metadata")
            timeout = timeout or kwargs.get("timeout")
            if metadata:
                tx.metadata.update(metadata)
            if timeout:
                tx.timeout = timeout
            return func(*args, **kwargs)
        return wrapper
    return do_work

