def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """

        if n == -1 and qid == -1:
            raise ValueError("Both n and qid cannot be -1")
        elif n == -1:
            params = {"last_qid": qid}
        elif qid == -1:
            params = {"n": n}
        else:
            params = {"last_qid": qid, "n": n}

        output_queue = deque()

        def handle_response(response):
            if response["code"] == "RECORD":
                record = response["fields"]
                if dehydration_hooks and "data" in record:
                    typ = type(record["data"])
                    dehydrate_fn = dehydration_hooks.get(typ)
                    if dehydrate_fn is not None:
                        record["data"] = dehydrate_fn(record["data"])
                output_queue.append(record)
            elif response["code"] == "SUCCESS":
                output_queue.append(response)
            elif response["code"] == "FAILURE":
                raise_from(ConsumerDiscardError(response["fields"]), None)
            else:
                raise_from(ConfluentError(response["fields"]), None)

        consumer = Consumer(handle_response, dehydration_hooks, hydration_hooks)
        self.frames.append(client.Frame(client.CODES["DISCARD"], params))
        self._dispatch_ongoing = True
        return Response(consumer, deque())

