def round_half_to_even(n):
    """
    Round a number to the nearest even integer.

    This is also known as "bankers rounding".

    :param n: The number to round.
    :return: The value of `n` rounded to the nearest even integer.
    """
    if not isinstance(n, (int, float)):
        raise TypeError("n must be a number")

    if n % 1 == 0.5:
        return int(n) + 1 if int(n) % 2 == 0 else int(n)
    else:
        return round(n)

