def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.

    Args:
        name: The name of the new Point subclass.
        fields: A list of field names for the Point subclass.
        srid_map: A mapping from SRID to the corresponding CRS name.

    Returns:
        A new Point subclass with the given name, fields, and SRID map.
    """
    try:
        class PointSubclass(Point):
            def __init__(self, *args):
                super().__init__(*args)
                self.x = None
                self.y = None
                self.srid = None
                self.crs = None

            def get_srid(self):
                return self.srid

            def get_crs(self):
                return self.crs

            def set_coords(self, x, y):
                self.x = x
                self.y = y

            def set_srid_crs(self, srid, crs):
                self.srid = srid
                self.crs = srid_map[srid]

            def __str__(self):
                return f"({self.x}, {self.y}, {self.srid}, {self.crs})"

        return PointSubclass
    except TypeError as e:
        raise TypeError("Invalid arguments passed to point_type()") from e

