def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple):
        raise ValueError("coord must be a tuple")
    if not len(coord) == 2:
        raise ValueError("coord must have length 2")
    if not np.isscalar(weight):
        raise ValueError("weight must be a scalar")

    x, y = coord
    if not np.isclose(x, int(x)):
        raise ValueError("x must be an integer")
    if not np.isclose(y, int(y)):
        raise ValueError("y must be an integer")

    if x < 0 or x >= self.size_x:
        return
    if y < 0 or y >= self.size_y:
        return

    self.array[y, x] += weight

