def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that prior is not None
    if prior is None:
        raise ValueError("Prior inventory is None")

    # Check that prior is an InventoryValidator object
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Prior inventory is not an InventoryValidator object")

    # Check that prior and self have the same number of items
    if len(self.inventory) != len(prior.inventory):
        raise ValueError("Prior and current inventories have different number of items")

    # Check that prior and self have the same items
    for idx, item in enumerate(self.inventory):
        if item.id != prior.inventory[idx].id:
            raise ValueError("Prior and current inventories have different items")

        # Check that the quantity of the item is non-negative
        if item.quantity < 0:
            raise ValueError("Quantity of item {} is negative in current inventory".format(item.name))

        # Check that the quantity of the item is less than or equal to the prior quantity
        if item.quantity > prior.inventory[idx].quantity:
            raise ValueError("Current inventory has more quantity of item {} than the prior inventory".format(item.name))

    return True

