def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    with zipfile.ZipFile(zip_path) as zfile:
        packages = {}
        for entry in zfile.infolist():
            if entry.filename.endswith(".xml"):
                package = entry.filename[:-4]
                if package not in packages:
                    packages[package] = {"packages": [], "metas": []}
                if entry.filename.endswith("_pkg.xml"):
                    packages[package]["packages"].append(entry.filename[:-9])
                elif entry.filename.endswith("_meta.xml"):
                    packages[package]["metas"].append(entry.filename[:-10])
                else:
                    packages[package]["other"].append(entry.filename)
        return packages

