    """Render the given version pieces into the requested style."""

    # Split the version pieces into major, minor, and patch components
    major, minor, patch = pieces.split('.')

    # Handle the requested style
    if style == 'full':
        # Return the full version with all components
        return '.'.join([major, minor, patch])
    elif style == 'short':
        # Return the short version with only the major and minor components
        return '.'.join([major, minor])
    elif style == 'major':
        # Return the major version with only the major component
        return major
    elif style == 'minor':
        # Return the minor version with only the major and minor components
        return '.'.join([major, minor])
    elif style == 'patch':
        # Return the patch version with only the patch component
        return patch
    else:
        # Raise a ValueError if an invalid style is provided
        raise ValueError('Invalid version style: ' + style)

