def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """

    # Initialize return value to None
    result = None

    # Check if path is a directory
    if os.path.isdir(path):
        # Check if path contains "0=*"
        if re.search(r"0=\*", os.listdir(path)):
            # Check if path contains "_root_"
            if re.search(r"_root_", os.listdir(path)):
                result = "root"
            # Check if path contains "inventory"
            elif re.search(r"inventory", os.listdir(path)):
                result = "file"
            else:
                # Check if path contains "namaste"
                if re.search(r"namaste", os.listdir(path)):
                    result = "object"
                else:
                    raise Exception("Path is not a root, object, or file.")
        else:
            raise Exception("Path does not contain '0=*' Namaste file.")
    else:
        raise Exception("Path is not a directory.")

    return result

