    for node in nodes:
        key, value = node
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            for inner_key, inner_value in value.value:
                merged_key = (key, inner_key)
                if merged_key not in seen_keys:
                    result.append((merged_key, inner_value))
                    seen_keys.add(merged_key)
                else:
                    result.append((merged_key, deep_merge_nodes([
                        (merged_key, inner_value),
