def subclasses(cls):
    '''Return all subclasses of a class, recursively'''
    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.append(c)

    seen.remove(cls)
    return list(seen)

