def parse_frequency(frequency):
    if not frequency:
        return None
    if frequency.lower() == 'always':
        return None
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError('Frequency should have two parts')
    amount = parts[0]
    unit = parts[1].lower()

    if unit == 'weeks':
        return datetime.timedelta(weeks=int(amount))
    elif unit == 'days':
        return datetime.timedelta(days=int(amount))
    elif unit == 'hours':
        return datetime.timedelta(hours=int(amount))
    elif unit == 'minutes':
        return datetime.timedelta(minutes=int(amount))
    elif unit == 'seconds':
        return datetime.timedelta(seconds=int(amount))
    else:
        raise ValueError('Invalid frequency unit')

