def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    check_arguments(iface, candidate, tentative)
    for method in iface.__abstractmethods__:
        if not hasattr(candidate, method):
            raise TypeError(f"Missing method '{method}' in {candidate}")

    # Check if the methods match the expected signature
    attrs = [getattr(candidate, method) for method in iface.__abstractmethods__]
