def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc:
        return explicit_mc

    bases = [base for base in bases if isinstance(base, type)]

    if not bases:
        raise TypeError("No bases given")

    bases = tuple(bases)

    if len(bases) == 1:
        return bases[0].__class__

    metaclasses = {base.__class__ for base in bases}

    metaclass = None

    for meta in reversed(metaclasses):
        if issubclass(meta, type):
            metaclass = meta
            break

    if not metaclass:
        raise TypeError("No metaclass found")

    return metaclass

