def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not public_key or not doc or not signature:
        raise ValueError("public_key, doc and signature are required")

    try:
        doc = etree.fromstring(doc)
    except etree.ParseError:
        raise ValueError("doc must be a valid XML string")

    sig = doc.find(".//")
    if sig is None:
        raise ValueError("doc must contain a signature element")

    try:
        nodes = []
        for node in doc.iter():
            if node.tag == sig.tag:
                nodes.append(node)
        nodes.remove(sig)
        signature = signature.strip()
        for node in nodes:
            if node.tag == sig.tag:
                if node.text.strip() != signature:
                    raise ValueError("signature mismatch")
    except ValueError:
        raise ValueError("signature mismatch")

    try:
        cert_file = _get_certificate(public_key)
    except FileNotFoundError:
        raise ValueError("certificate file not found")

    try:
        pub_key = RSA.importKey(cert_file.text)
    except RSAError:
        raise ValueError("certificate is not a valid RSA key")

    message = "".join([etree.tostring(node) for node in nodes])
    try:
        verifier = PKCS1_v1_5.new(pub_key)
        digest = SHA.new(message)
        verifier.verify(digest, signature)
    except TypeError:
        raise ValueError("signature is not valid")

